// The site's icon library: every built-in icon the admin can pick, in one
// list. Each is a single-colour SVG drawn in currentColor, so it takes the
// colour of the text around it (white everywhere on this site).
//
// To add one, append an entry: a key (lowercase, dashes; it's what content
// stores, so never rename one in use), a label, a group, where it came from
// and its license, search keywords and the SVG:
// - "stroke" icons are Lucide's: viewBox "0 0 24 24" and the inner elements
//   of the icon's SVG from lucide.dev
// - "fill" logos are one colour. Run `node scripts/icon-box.mjs logo.svg` for
//   the viewBox and body, which fits the logo to the same optical size as the
//   rest (a wide logo spans the box, a square one sits smaller in it)
// Logos keep their owners' trademarks: they're here to name the technology.
// Every icon's source and license is listed in ICONS.md, next to this file

export type IconGroup = "icons" | "tech" | "roblox";

export type LibraryIcon = {
  key: string;
  label: string;
  group: IconGroup;
  /** Where the artwork comes from */
  source: string;
  license: string;
  /** Extra words the picker's search matches, besides the label */
  keywords: string[];
  /** Lucide icons are drawn with strokes, logos with fills */
  style: "stroke" | "fill";
  viewBox: string;
  /** The SVG's inner markup, in currentColor or no colour at all */
  body: string;
};

